import{_ as a}from"./chunks/2bcbea751f7e49815a6f.CywLdGoY.js";import{_ as r}from"./chunks/8549cc296d59b11fd6cd.Qamv1ACt.js";import{_ as o,C as n,o as s,c as l,j as p,a as i,E as h,a6 as c}from"./chunks/framework.CnPv4DE1.js";const q=JSON.parse('{"title":"为什么你不会改变（如何重塑自己）","description":"","frontmatter":{"title":"为什么你不会改变（如何重塑自己）","originalTitle":"Why You Won’t Change (How To Reinvent Yourself)","date":"2022-06-18","originalUrl":"https://thedankoe.com/letters/why-you-wont-change-how-to-reinvent-yourself/","minutes":11,"sourceHash":"59ede2cad9ce5512865043839f4f6d5ef9c2438f6c7cf6dd2ebf07288f8bee46","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-you-wont-change-how-to-reinvent-yourself/"}]]},"headers":[],"relativePath":"letters/why-you-wont-change-how-to-reinvent-yourself.md","filePath":"letters/why-you-wont-change-how-to-reinvent-yourself.md"}'),f={name:"letters/why-you-wont-change-how-to-reinvent-yourself.md"};function m(d,e,u,g,k,b){const t=n("ArticleMeta");return s(),l("div",null,[e[0]||(e[0]=p("h1",{id:"为什么你不会改变-如何重塑自己",tabindex:"-1"},[i("为什么你不会改变（如何重塑自己） "),p("a",{class:"header-anchor",href:"#为什么你不会改变-如何重塑自己","aria-label":'Permalink to "为什么你不会改变（如何重塑自己）"'},"​")],-1)),h(t),e[1]||(e[1]=c('<p><a href="https://www.youtube.com/embed/QBESNoCeZWY?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>小时候，我曾是个童子军（boy scout）。</p><p>每个星期二晚上，我都会来到我以前去的教堂，在空中举起三根手指敬礼，并背诵童子军誓词。</p><p>我们的队伍会讨论每周的日程安排，为了我们感兴趣的荣誉徽章而努力，并计划下一次的露营之旅。</p><p>每年我们都会有一次被称为“高度冒险（High Adventure）”的旅行。</p><p>这些冒险是为期一周的露营之旅。有时我们会去建造自己的雪洞并在里面睡觉。还有些时候，我们会和全州各地的其他童子军队伍汇合，为了不同的荣誉徽章而努力（比如生存荣誉徽章，我必须用树皮搭建一个庇护所并“撑过”这一夜），到了晚上，我们会围坐在营火旁玩游戏。</p><p>有一年，我们决定去卡塔利娜岛（Catalina Island）。我们定下了一个宏大的目标：划着皮划艇环游全岛，并沿途在不同的海滩上露营。</p><p>当那天到来时，我们开车前往加利福尼亚（California），登上了渡轮。在玩了一个小时的纸牌游戏、喝了几杯无酒精的椰林飘香（virgin Piña Coladas）之后，我们登陆了卡塔利娜岛。</p><p>因为我们到得晚了，我们不得不<em>匆忙赶去租皮划艇并几乎立刻“起航”</em>。没有休息时间，稍微有点让人紧张。</p><p>我们两两结对，把超大的行李袋绑在小船的后面，指望我们之前拿到的独木舟（一种类似于皮划艇的船）荣誉徽章能让我们拥有足够的技巧，去应对接下来在海上的5个小时。</p><h2 id="生活总是波浪式前行" tabindex="-1">生活总是波浪式前行 <a class="header-anchor" href="#生活总是波浪式前行" aria-label="Permalink to &quot;生活总是波浪式前行&quot;">​</a></h2><p>大约有一个小时的时间，水面一直很平静。没有任何问题。非常宁静。</p><p>直到海浪开始变得越来越深。我们以为这只是暂时的，因为我们看不见从岛屿另一边正席卷而来的风暴。我们离悬崖太近了，除了右边晴朗的天空，什么也看不见。</p><p>长话短说，<em>我们在风暴中心被困住了</em>，而此时我们的冒险才刚刚过半。</p><p>海浪变得至少有10英尺高。</p><p>我们的队伍开始被冲散——强壮有力的在前面，虚弱的落在了后面。</p><p><strong>我和我的哥们儿多次翻船。</strong> 浑身湿透。寒冷刺骨。差点弄丢了船桨。什么也听不见。密集的暴雨像针扎一样打在我们露出水面的身体部位上。</p><p>我的行李袋有一次掉了下去——把我所有的食物和衣服都泡透了——迫使我跳进海里去抓它，并试图把它重新绑好。</p><p>更不用说……我们还在<em>逆着</em>强风划桨。朝着我们海滩目的地的进展几乎为零。</p><p><strong>这是我人生中唯一一次真的以为自己要完蛋了的时刻。</strong></p><p>只有当我们处于浪尖，而童子军领队们处于浪谷时，才能看到他们橙色的船桨。在风暴开始的大约30分钟后，我们就和他们走散了。</p><p>我和我的皮划艇搭档经历了几轮拼死划桨，然后又接受自己即将殒命的阶段。在风暴中瘫软下来。充满了挫败感。向海浪屈服，祈祷它们不要把我们拍在距离我们大约100-200英尺远的悬崖上。</p><p>此时时间已经变得模糊不清。我们终于看到了海岸，重新燃起了希望，并用他妈的最大的力气拼死划桨，只为抵达陆地。</p><p>冲上海岸后，我们把皮划艇拖到海滩上，然后瘫倒在地。我们所有人都因为寒冷而微微抽搐，试图尽可能多地把身体暴露在阳光下取暖。</p><p>那些落后的人大约在一小时后和岛上的救援队一起出现了。我所有的食物和衣服仍然是湿透的（最终在我们睡觉时被鸟给吃了）。</p><p>毫无疑问，我们不得不缩短了行程，在第二天就离开了。</p><p>我们可以从这个故事中学到很多东西，它很好地模拟了<a href="https://thedankoe.com/if-you-feel-lost-understand-these-3-phases-of-life/" target="_blank" rel="noreferrer">人生强度的周期</a>——但我想要描绘一幅不同的画面。</p><h2 id="巅峰与谷底" tabindex="-1">巅峰与谷底 <a class="header-anchor" href="#巅峰与谷底" aria-label="Permalink to &quot;巅峰与谷底&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>当我们处在浪尖时，就有了希望。</p><p>当我们深陷浪谷时，希望就变得渺茫。</p><p>当你觉得站在世界之巅时，没有什么能阻挡你。</p><p>当你跌落海底时，任何事物都能让你停滞不前。</p><blockquote><p>你置身于寒冷之中，你开始发抖，为什么？因为你在抗拒寒冷，你绷紧肌肉去抵御寒冷，结果你变得步履蹒跚。放轻松，顺应寒冷，放松下来。\\</p><p>—— 艾伦·瓦茨（Alan Watts）</p></blockquote><p>在经典力学中，<em>谐振子（harmonic oscillator）是一个试图保持平衡</em>（稳态）<em>的系统</em>。</p><p>你需要知道的80/20核心法则是，当平衡被打破时，它会以同等幅度向相反方向反弹，并最终使自身恢复到平衡状态。</p><p>我们的大脑也不例外。</p><p>我们在生活中渐渐期待的那些高潮，<em>总是</em>伴随着低谷而来。总是如此。如果你没有认出那是一个低谷——恭喜你，在应对深陷泥潭时遭遇的战斗中，你已经培养出了一定程度的正念。</p><p>我们的大脑是一个由复杂系统组成的网络，随着时间的推移，通过正反馈和负反馈被条件化。系统就是这样运作的，对吧？</p><p>如果你收到了负反馈，你就不会再那样做了。</p><p>如果你收到了正反馈，你就会再做一次。</p><p>如果你因为做某件特定的事而持续收到正反馈，它就会在你的心灵深处根深蒂固。这种行为、信念或思维模式会变得习惯化。它们会自动运转。</p><p>就像训狗一样。它们听不懂人类的语言，但它们能把语气和模式与某些含义联系起来——不管是积极的还是消极的。如果一条狗出现了次优行为，你就会用某种语气或策略给它负反馈。这样做足够多次，它们最终会改变自己的行为，接着你就可以用正反馈来强化（条件化）它。</p><p>大脑的这种可塑性可能非常危险（在无意识时），也可能非常有利（在有意识时）。</p><p>这表明我们有能力去重新调节、重新编程或重新连接我们的大脑——但是，我们如同谐振子一般的心智，可不会轻易放过我们。</p><p><em><strong>无耻的Koe信件中插广告</strong>：<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者只需支付5美元即可加入 Modern Mastery</a>——加入1000多名会员的行列，获取170多项生活和商业策略、路线图、实时培训以及个性化帮助。</em></p><h2 id="身份的层次" tabindex="-1">身份的层次 <a class="header-anchor" href="#身份的层次" aria-label="Permalink to &quot;身份的层次&quot;">​</a></h2><p>如果你想改变你的生活，你必须改变你的身份。</p><p>一个健康的人不会把健康饮食视为一种差事。<em>他们本身就是健康饮食的人</em>。没有其他选择。对他们来说，这是一种享受。</p><p>一个生意人不会把每天早上的专注工作视为负担。<em>他们本身就是每天早上把工作做完的人</em>。</p><p>改变你的信念、身份和生活并没有听起来那么简单。</p><p>我希望你把自己的大脑想象成一座城市。具体来说，是华盛顿州西雅图市（Seattle Washington）。</p><p>在1889年，一口胶水锅被打翻，引发了一场大火，摧毁了这座城市的一大片区域。为什么？</p><p>除了那个自以为聪明、往燃烧的胶水上泼水（导致火势迅速蔓延）的人之外，这座城市的根基也建立在一个糟糕的基础之上。木制的建筑。木制的污水系统。粗劣的施工建设——全都是这样。</p><p>人类的心理天生就是为了生存而连线的。当你的信念、身份或生命受到威胁时——大脑会向身体发出信号，你的注意力开始变窄，并且你会对自己脑海中泛滥的想法给予过多的关注。平衡被打破了，你的大脑开始做出相应的反应，以把你带回到稳态。</p><p>问题在于，我们生活在一个与我们祖先完全不同的世界里。我们很少在肉体层面上受到威胁。我们大多数人都有住所，能够获取食物，并且有能力谋生。</p><p>人类是唯一将信念的死亡等同于肉体死亡的生物。</p><p>这种生存机制可能是危险且具有破坏性的。如果你试图通过做一个微小的改变来改变你的身份，你打破了平衡（或者说打翻了一锅胶水），就可能会把你大脑中经过多年建设（条件化）而成的那部分城市给点燃。</p><p>当你试图重建城市的一角时，它可能会威胁到整个根基。当你处于浪谷时，你什么也看不见。你可能会失去抵达海岸的希望。你可能会翻几次皮划艇。</p><p>当你深陷人生的泥潭时，你可能不会把它解读为一件好事。你可能会把它当成负反馈——从而固化出一种错误的系统性思维模式——并因此去回避任何威胁到那个“并不利于高质量生活”的旧有身份的事物。</p><p>这就是这一切的挑战所在。新罗马是建立在古罗马之上的（而且它不是一天建成的！）。新西雅图是建立在老西雅图之上的。</p><p>所有的建筑、地基、街道和其他网络都是相互连接的。层层叠叠，互相依存以实现正常运转。一系列系统协同工作，执行它被赋予的使命。移除某个特定部分，可能会对系统的功能造成暂时性的破坏。</p><p>这就类似于你的身份——我们通过层层的叙事、信念和根深蒂固的思维模式来理解自己，而这些东西构筑了我们大脑运转的最佳状态。</p><p>如果我重建了我的故事，我还会存在吗？如果我揭露并重塑了过去的创伤会怎样？如果我质疑自己坚守的宗教信仰会怎样？如果我的整个生活不再围绕着教堂转，我还是“我”吗？如果我不日复一日地做着同样的事情，我的生活会变成什么样？</p><p>这将很难被理清——这是肯定的。</p><h2 id="如何重塑自己" tabindex="-1">如何重塑自己 <a class="header-anchor" href="#如何重塑自己" aria-label="Permalink to &quot;如何重塑自己&quot;">​</a></h2><p>重塑自己有2条路线：</p><p><strong>1) 跌入谷底。</strong></p><p>通过感受你生命中最低潮的低谷，<a href="https://thedankoe.com/get-mad-at-where-you-are-in-life/" target="_blank" rel="noreferrer">你开始对自己的生活现状感到厌倦。</a></p><p>你变得极度清醒，意识到是什么在阻碍着你。你深深挖掘你的身份层，找到那个最适合移除的部件，以便向相反的方向全速发射。</p><p>这伴随着大量的痛苦和折磨——而且通常是不可控的。把你这座隐喻上的城市烧毁，可能会引发一些更深层次的问题，导致你在几年后的人生中再次跌入谷底。</p><p>我遇到的每一个跌入谷底的人，都是因为生活本身塞给他们的一把烂牌。</p><p>还有一个更好的选择。一个完全在你的掌控之中的选择。</p><p><strong>2) 积累小胜。</strong></p><p>大家都听过詹姆斯·克利尔（James Clear）的“每天进步百分之一”这句咒语。</p><p>它蕴含着巨大的力量。</p><p>当你一片一片地重建你的城市时，你建造的将会是新西雅图（而不需要烧毁半个城市）。</p><p>你该从哪里开始呢？</p><p>从彻底理清你的愿景（vision）和反愿景（anti-vision）开始。</p><blockquote><p>如果你不知道自己想要什么，那就弄清楚你不想要什么，然后向相反的方向努力。</p><p>—— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1537030087874420738?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年6月15日</a></p></blockquote><p>多亏了我们大脑的负面偏见，我们很容易就能察觉到自己不想要什么，并开始向相反的方向努力。</p><p>当你<a href="https://thedankoe.com/how-to-create-a-life-of-meaning-money-impact-as-fast-as-humanly-possible/" target="_blank" rel="noreferrer">为你的未来勾勒愿景</a>时，觉察之光将照亮你的盲区。</p><blockquote><p>如果你感到迷茫，答案是教育。\\</p><p>如果你受过教育，答案是行动。\\</p><p>如果你正在行动，答案是坚持。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1508796620569206784?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">March 29, 2022</a></p></blockquote><p>当你将愿景逆向工程为10年、1年和月度目标时——你开始清楚你需要做什么才能实现该愿景。</p><p>现在，我们可以将事情分解为优先任务。</p><p>从那时起——这也是迄今为止最重要的一步——就是减少采取行动的阻力。</p><p>你能迈出的最小的心理、生理、情感或财务层面的步伐是什么？</p><p>是穿上运动鞋走出家门吗？</p><p>是挪动一条腿从沙发上起来吗？</p><p>是投资25美元买一门课程，以表明你决心提高自己的技能吗？</p><p>是读一本书的第一个字，还是写下你自己书的第一个字？</p><h2 id="主动构建你的人生" tabindex="-1">主动构建你的人生 <a class="header-anchor" href="#主动构建你的人生" aria-label="Permalink to &quot;主动构建你的人生&quot;">​</a></h2><p>这不是一个轻松的过程。你仍然像在一艘处于风暴中心的隐喻性皮划艇上。生活是混乱的。通过愿景和设定目标来建立意识秩序，是我们获得对生活的确定感和控制感的方式。</p><p>因为我们所处的时代与公元前5世纪相似——世界上流传着大量的信息和思想。人们正在失去对外部指定的等级目标的信任，无论它是来自企业文化、有组织的宗教，还是正规教育。</p><p>正因如此，你必须在构建自己的人生中发挥主动作用。这需要个人责任感、巨大的自信，并认清没有人会来拯救你。</p><p><a href="https://thedankoe.com/how-to-make-money-as-a-creative-on-the-internet/" target="_blank" rel="noreferrer">收集和整理世界上丰富的信息</a>，并将其以一种能带来丰厚收入源、散发健康活力、让头脑有序以及让灵魂产生连结的方式组织起来，这一切的决定权都在你手中。</p><blockquote><p>忠言逆耳：\\</p><p>你的大部分限制都是自我施加的。如果你想要某样东西，总会有办法——只是你的大脑不让你看到它。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1381538141895528448?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">April 12, 2021</a></p></blockquote><p>如果你认为自己正处于风暴的中心，你就会处于风暴之中。</p><p>如果你认为自己是在波浪过山车上享受乐趣，你就会获得乐趣。</p><p>你如何主动构建你的人生？</p><p>通过意识、创造力和意图。</p><p>最简单的方法就是把你生活的每一个方面都当作一个项目来对待。</p><p><img src="'+r+'" alt=""></p><p>以下是你开始改变生活所需的一切：</p><ol><li>买一个空白笔记本</li><li>用大写字母写上“我的科学日志”</li><li>把你的思想、身体、灵魂和业务当作一生的项目来对待</li><li>记录观察结果，测试微小的改变，分析结果，并在有效的事情上加倍下注</li></ol><p>通过默默的观察保持清醒和觉察（这可以应用于你的心理、身体、财务和精神项目）。</p><p>自我教育以扩展意识并发现新路径。</p><p>提出假设，并用能解决你问题的方案进行实验。</p><p>分析结果并获得反馈，这将开始重塑你大脑中系统的网络。</p><p>记录一个可复制的流程，这可以帮助其他人，并为你带来<em>更多</em>的反馈。</p><p>如此反复。</p><p>你经历了超过18年的条件塑造，才走到今天这一步。</p><p>别指望一夜之间能有多大进展。</p><p>朋友们，这就是你重塑自我的方式。</p><p>— Dan Koe</p><p><strong>本周动态</strong></p><p>一部关于我个人故事的全新YouTube视频发布了。讲述了我是如何在大多数在线业务模式上失败，又是如何将其转变为年入50万美元的一人企业的。</p><p><a href="https://www.youtube.com/watch?v=L9qh1-T_YVo" target="_blank" rel="noreferrer">你可以在这里观看。</a></p><p>我们正在为下周Modern Mastery内部与Dakota Robertson一起进行的直播培训做准备。我们将探讨如何进入Twitter代写（Ghostwriting）领域、拿下你的第一个客户，以及你需要学习的技能。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Koe Letter的读者可以点击这里以5美元加入。</a></p><p>至于那些好奇为什么最近没有播客更新的人——由于Digital Economics的发布，我不得不优先分配我的注意力。当需要重新聚焦时，播客总是第一个被我暂时搁置的项目。我很快就会恢复原来的更新频率，或者开始制作一些本周核心思想精简版（5-10分钟的单集）。</p><p>如果你对希望看到的播客风格有什么建议，请通过回复这封邮件告诉我！</p><hr><p><a href="/en/letters/why-you-wont-change-how-to-reinvent-yourself">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',124))])}const v=o(f,[["render",m]]);export{q as __pageData,v as default};
